import pathlib,urllib.parse,http.client,ipaddress,json,base64,tempfile,os
def checked(url):
    if not isinstance(url,str) or any(ord(c)<32 or ord(c)==127 for c in url):raise ValueError('invalid URL')
    p=urllib.parse.urlsplit(url)
    try:address=ipaddress.ip_address(p.hostname or '');port=80 if p.port is None else p.port
    except ValueError as e:raise ValueError('numeric loopback URL required') from e
    if p.scheme!='http' or not address.is_loopback or p.username is not None or p.password is not None or not 1<=port<=65535:raise ValueError('only HTTP loopback endpoints without userinfo')
    # Fragment is local navigation state and must never be sent in a request.
    clean=urllib.parse.urlunsplit((p.scheme,p.netloc,p.path or '/',p.query,''))
    target=(p.path or '/')+('?' + p.query if p.query else '')
    return clean,(str(address),port),target
def execute(url,output,method='GET',body=b'',headers=None,max_redirects=5):
    if method not in {'GET','POST'} or not isinstance(body,bytes):raise ValueError('GET/POST and bytes body required')
    if type(max_redirects) is not int or not 0<=max_redirects<=5:raise ValueError('redirect bound must be 0..5')
    supplied={} if headers is None else headers
    if not isinstance(supplied,dict):raise ValueError('headers must be a mapping')
    working={}
    for name,value in supplied.items():
        if not isinstance(name,str) or not isinstance(value,str) or name.lower() not in {'authorization','content-type','user-agent'} or any(ord(c)<32 or ord(c)==127 for c in name+value):raise ValueError('unsupported or unsafe header')
        if name.lower() in working:raise ValueError('duplicate case-insensitive header')
        working[name.lower()]=value
    url,origin,target=checked(url);seen=set();history=[];redirects=0
    while True:
        key=(method,url)
        if key in seen:raise ValueError('redirect cycle')
        seen.add(key)
        conn=http.client.HTTPConnection(origin[0],origin[1],timeout=.5)
        try:
            conn.request(method,target,body=body,headers=working)
            response=conn.getresponse();status=response.status
            history.append({'url':url,'method':method,'status':status})
            if status in {301,302,303,307,308}:
                if redirects>=max_redirects:raise ValueError('too many redirects')
                location=response.getheader('Location')
                if not location:raise ValueError('missing redirect location')
                next_url,next_origin,next_target=checked(urllib.parse.urljoin(url,location))
                if next_origin!=origin:working.pop('authorization',None)
                if status==303 or (status in {301,302} and method=='POST'):
                    method='GET';body=b'';working.pop('content-type',None)
                url,origin,target=next_url,next_origin,next_target;redirects+=1
                continue
            payload=response.read(262145)
            if len(payload)>262144:raise ValueError('response body too large')
            result={'history':history,'status':status,'body_base64':base64.b64encode(payload).decode()}
            break
        finally:conn.close()
    output=pathlib.Path(output);fd,temp=tempfile.mkstemp(prefix='.trace-',dir=output.parent)
    try:
        with os.fdopen(fd,'w') as stream:json.dump(result,stream);stream.flush();os.fsync(stream.fileno())
        os.replace(temp,output)
    finally:
        if os.path.exists(temp):os.unlink(temp)
    return result
```

跳转不是简单重复发送原请求。必须同时处理方法变化、消息体、来源边界、片段与上限；Cookie、HTTPS降级、浏览器缓存等不在本练习实现范围，不能拿此教学客户端代替完整浏览器。

原理补充：
可能先命中浏览器/系统缓存，否则经解析器取得地址；选择路径并建立TCP+TLS或QUIC连接，校验证书和目标身份，发送包含Host/authority的HTTP请求。入口代理、应用及依赖处理后响应，浏览器继续请求资源并渲染。代理、缓存、重用连接和HTTP版本会改变步骤，排查应分阶段记录耗时。

